/* ===================== BÀI 48 · Xung, encoder và giới hạn tài nguyên ===================== */
/* Bài 48 · Xung, encoder và giới hạn tài nguyên (AMTS-EMB-001-M12-L04, MC51-048) — sinh bởi tools/author/mcu8051/l48.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 (thiết bị ảo đo lường/điều khiển tải: platform/js/56-mcu51-ana.js) và bài tập chấm tự động. Lời giải không nằm ở đây. */
const P48=[{"label":"Ví dụ: Đếm xung bằng Timer 0 trong cửa sổ 10 ms","code":"; Đếm xung kênh A bằng Timer 0 chế độ đếm (chân T0 = P3.4)\n; trong cửa sổ khoảng 10 ms\n        ORG     0000H\n        MOV     TMOD,#05H               ; Timer 0: đếm sự kiện, 16 bit\n        MOV     TL0,#0\n        MOV     TH0,#0\n        SETB    TR0                     ; mở cửa sổ đếm\n        MOV     R5,#20                  ; 20 x 501 + 1 = 10 021 chu kỳ\nCUA:    MOV     R6,#249\n        DJNZ    R6,$\n        DJNZ    R5,CUA\n        CLR     TR0                     ; đóng cửa sổ\n        MOV     30H,TL0                 ; số sườn xuống ở T0\n        MOV     31H,TH0\n        SJMP    $\n        END\n","note":"Timer 0 đếm sườn xuống ở chân T0 (A nối P3.4) trong cửa sổ khoảng 10 ms: TL0 = 0AH = 10 xung → ≈ 1 000 Hz → 3 000 vòng/phút với 20 xung/vòng. Đổi tốc độ thành 5 000 xung/s rồi chạy lại: khoảng 50 xung. CPU không tốn lệnh nào cho từng xung.","dev":{"enc":{"a":"P3.4","b":"P3.3","pps":1000,"cnt":"30"}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Giải mã chiều bằng thăm dò kênh A, B","code":"; Giải mã chiều bằng thăm dò: ở sườn xuống của A đọc B\n; B = 1: thuận (+1), B = 0: ngược (-1). Đếm 8 sườn.\n        ORG     0000H\n        MOV     30H,#0                  ; vị trí (số có dấu)\n        MOV     R7,#8\nCHO1:   JNB     P3.2,CHO1               ; chờ A = 1\nCHO0:   JB      P3.2,CHO0               ; chờ A xuống 0\n        JNB     P3.3,NGUOC\n        INC     30H\n        SJMP    TIEP\nNGUOC:  DEC     30H\nTIEP:   DJNZ    R7,CHO1\n        SJMP    $\n        END\n","note":"Thăm dò: chờ A lên 1, chờ A xuống 0, đọc B. Quay thuận 1 000 xung/s nên mỗi lần B = 1 → +1; sau 8 sườn ô 30H = 08H. Đổi tốc độ thành số âm rồi chạy lại: 30H = F8H (−8).","dev":{"enc":{"pps":1000,"cnt":"30"}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Đếm bằng ngắt INT0, quay ngược","code":"; Đếm bằng ngắt INT0 kích sườn (A = P3.2), đọc B trong ngắt\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; vector INT0\n        JNB     P3.3,GIAM               ; đọc B ngay: 0 = quay ngược\n        INC     30H\n        RETI\nGIAM:   DEC     30H\n        RETI\nMAIN:   MOV     30H,#0\n        SETB    IT0                     ; INT0 kích sườn xuống\n        CLR     IE0                     ; xóa cờ đã bật lúc còn kích mức\n        SETB    EX0\n        SETB    EA\n        MOV     R5,#20                  ; chờ khoảng 10 ms\nCUA:    MOV     R6,#249\n        DJNZ    R6,$\n        DJNZ    R5,CUA\n        CLR     EA\n        SJMP    $\n        END\n","note":"Quay ngược 2 000 xung/s, ngắt INT0 ở mỗi sườn xuống A, đọc B = 0 → trừ 1. Sau khoảng 10 ms: 30H = ECH = −20, khớp số sườn thật. Thử bỏ dòng CLR IE0: số đếm thành −21 (một lần ngắt “ma” lúc bật EA).","dev":{"enc":{"pps":-2000,"cnt":"30"}},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Thăm dò chậm hơn xung, mất gần hết sườn","code":"; Bẫy: thăm dò A mỗi 60 chu kỳ, xung 50 µs -> mất xung\n        ORG     0000H\n        MOV     30H,#0                  ; số sườn xuống đếm được\n        MOV     R7,#100                 ; 100 lần lấy mẫu\n        MOV     C,P3.2\n        MOV     20H.0,C                 ; mẫu trước\nLAP:    MOV     C,P3.2                  ; mẫu mới\n        JC      LUU                     ; nay 1: không phải sườn xuống\n        JNB     20H.0,LUU               ; trước 0, nay 0: không đổi\n        INC     30H                     ; trước 1, nay 0: sườn xuống\nLUU:    MOV     20H.0,C\n        MOV     R6,#25                  ; việc khác: 51 chu kỳ\n        DJNZ    R6,$\n        DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Xung 20 000/s: mỗi mức A giữ 25 µs, nhưng vòng lặp đọc A mỗi 58 … 61 chu kỳ máy. Chương trình đếm 18 (12H), encoder đã có 118 sườn: bảng thiết bị báo lệch 100 xung. Thử tốc độ 200 xung/s: đếm đúng.","dev":{"enc":{"pps":20000,"cnt":"30"}},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Chương trình ngắt dài hơn khoảng cách xung","code":"; Bẫy: chương trình ngắt dài hơn khoảng cách hai xung\n; Timer 1 đo cửa sổ 5 ms bằng phần cứng\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; vector INT0\n        JNB     P3.3,GIAM\n        INC     30H\n        SJMP    XULY\nGIAM:   DEC     30H\nXULY:   INC     31H                     ; số lần vào ngắt\n        MOV     R6,#40                  ; \"xử lý\" thêm 81 chu kỳ\n        DJNZ    R6,$\n        RETI\nMAIN:   MOV     30H,#0\n        MOV     31H,#0\n        MOV     TMOD,#10H               ; Timer 1 chế độ 1\n        MOV     TH1,#0ECH               ; 65536 - 5000 = EC78H\n        MOV     TL1,#78H\n        SETB    IT0                     ; INT0 kích sườn xuống\n        CLR     IE0                     ; xóa cờ đã bật lúc còn kích mức\n        SETB    EX0\n        SETB    EA\n        SETB    TR1\n        JNB     TF1,$                   ; chờ hết 5 ms\n        CLR     EA\n        CLR     TR1\n        SJMP    $\n        END\n","note":"Mỗi lần ngắt khoảng 90 chu kỳ máy nhưng sườn đến mỗi 50 µs. Tới khi chương trình dừng (≈ 5,2 ms, vì các lần ngắt nối đuôi làm vòng chính chậm thấy TF1): 104 sườn thật, chỉ 56 lần vào ngắt (31H = 38H), và vì B được đọc muộn nên chiều sai một nửa số lần: vị trí 30H = 02H thay vì 104.","dev":{"enc":{"pps":20000,"cnt":"30"}},"fosc":12000000,"speed":"real"}];
const sim48=makeSim51(document.getElementById("m51-l48"),{id:"s48",presets:P48,ram:256});
makeEx51(document.getElementById("ex-l48"),"l48",[{"t":"Chiều quay ở sườn xuống của kênh A","d":"<p>Encoder nối A = <code>P3.2<\/code> (INT0), B = <code>P3.3<\/code>. Chương trình ngắt INT0 (kích sườn xuống A) vừa đọc cả cổng P3 vào ô <code>31H<\/code>. Quay thuận thì lúc A xuống, B đang bằng 1; quay ngược thì B bằng 0. Cập nhật bộ đếm vị trí có dấu <code>30H<\/code>: B = 1 thì cộng 1, B = 0 thì trừ 1 (8 bit, vòng quanh). Ô 31H giữ nguyên; các bit khác của 31H là mức của chân khác, không được dùng.<\/p><p>Ví dụ: 30H = 05H, 31H = FBH → <code>30H = 06H<\/code>; 30H = 05H, 31H = F3H → <code>30H = 04H<\/code>.<\/p>","start":"; Sườn xuống A vừa xảy ra; 31H = ảnh P3 đọc ngay sau đó.\n; Cập nhật bộ đếm có dấu 30H theo kênh B.\n        ORG     0000H\n        MOV     A,31H\n        JB      ACC.2,TANG              ; kiểm tra kênh B?\n        DEC     30H\n        SJMP    XONG\nTANG:   INC     30H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x31":251}},"expect":{"iram":{"0x30":6,"0x31":251}}},{"setup":{"iram":{"0x30":5,"0x31":243}},"expect":{"iram":{"0x30":4,"0x31":243}}},{"setup":{"iram":{"0x30":127,"0x31":251}},"expect":{"iram":{"0x30":128,"0x31":251}}},{"setup":{"iram":{"0x30":0,"0x31":243}},"expect":{"iram":{"0x30":255,"0x31":243}}},{"setup":{"iram":{"0x30":16,"0x31":8}},"expect":{"iram":{"0x30":17,"0x31":8}}},{"setup":{"iram":{"0x30":16,"0x31":247}},"expect":{"iram":{"0x30":15,"0x31":247}}},{"setup":{"iram":{"0x30":128,"0x31":12}},"expect":{"iram":{"0x30":129,"0x31":12}}}]},"hints":["Code mẫu kiểm bit 2 — đó là chính kênh A (luôn bằng 0 ngay sau sườn xuống), nên lúc nào cũng trừ.","P3.3 là bit 3 của ảnh cổng: JB ACC.3,… sau MOV A,31H (hoặc ANL A,#08H rồi JNZ)."],"why":"Hai kênh lệch 90°: tại sườn xuống của A, kênh B đang ở giữa nửa chu kỳ của nó nên có mức ổn định — 1 khi quay thuận, 0 khi quay ngược. Đọc đúng bit của chân B (bit 3) là đủ để biết chiều."},{"t":"Vị trí 16 bit cộng bước có dấu","d":"<p>Bộ đếm 8 bit tràn sau 128 xung — quá ít cho một trục quay nhiều vòng. Vị trí 16 bit có dấu nằm ở <code>30H<\/code> (byte cao) : <code>31H<\/code> (byte thấp). Mỗi 1 ms chương trình ngắt cộng thêm bước có dấu <code>32H<\/code> (−128…+127, bù 2) đã đếm được. Viết phép cộng: 30H:31H ← 30H:31H + 32H (mod 65536); 32H giữ nguyên.<\/p><p>Ví dụ: 0100H + 5 → <code>30H = 01H, 31H = 05H<\/code>; 0002H + (−3) → <code>FFFFH<\/code>.<\/p>","start":"; Vị trí 16 bit 30H:31H (cao:thấp) += bước có dấu 32H\n        ORG     0000H\n        MOV     A,31H\n        ADD     A,32H                   ; byte thấp\n        MOV     31H,A\n        MOV     A,30H\n        ADDC    A,#0                    ; byte cao: chỉ cộng cờ nhớ\n        MOV     30H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":5}},"expect":{"iram":{"0x30":1,"0x31":5,"0x32":5}}},{"setup":{"iram":{"0x30":0,"0x31":2,"0x32":253}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":253}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":1}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":1}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":255}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":255}}},{"setup":{"iram":{"0x30":18,"0x31":52,"0x32":127}},"expect":{"iram":{"0x30":18,"0x31":179,"0x32":127}}},{"setup":{"iram":{"0x30":18,"0x31":52,"0x32":128}},"expect":{"iram":{"0x30":17,"0x31":180,"0x32":128}}},{"setup":{"iram":{"0x30":127,"0x31":255,"0x32":1}},"expect":{"iram":{"0x30":128,"0x31":0,"0x32":1}}}]},"hints":["Code mẫu chỉ cộng cờ nhớ vào byte cao. Với bước −3 = FDH: byte thấp 02H + FDH = FFH, không nhớ, byte cao còn 00H — kết quả 00FFH thay vì FFFFH.","Bước âm phải mở rộng dấu thành 16 bit: byte cao của bước là FFH khi bit 7 của 32H bằng 1, ngược lại 00H.","Byte cao của bước là phần mở rộng dấu; byte cao cộng có nhớ."],"why":"Số bù 2 8 bit d mở rộng thành 16 bit bằng cách chép bit dấu vào 8 bit cao (FFxxH khi âm). Khi đó phép cộng 16 bit thông thường (ADD byte thấp, ADDC byte cao) cho đúng kết quả cho cả bước dương lẫn âm, kể cả lúc mượn/nhớ qua byte cao."},{"t":"Giải mã x4 không quá 20 chu kỳ","d":"<p>Giải mã đủ 4 sườn (x4): mỗi lần A hoặc B đổi, chương trình ngắt so trạng thái cũ với trạng thái mới. Ô <code>30H<\/code> chứa trạng thái cũ s = 2B + A (0…3). Ô <code>31H<\/code> là ảnh P3 vừa đọc (A = bit 2, B = bit 3). Quay thuận, (A, B) đi 00 → 10 → 11 → 01 → 00, tức s: 0 → 1 → 3 → 2 → 0; quay ngược theo chiều ngược lại. Viết chương trình: thuận thì <code>32H<\/code> + 1, ngược thì 32H − 1 (8 bit, vòng quanh), không đổi thì giữ nguyên; nếu cả A và B cùng đổi (“nhảy cóc”, xung bị mất) thì 32H giữ nguyên và <code>33H<\/code> + 1. Cuối cùng ghi trạng thái mới vào 30H. Code mẫu đúng nhưng dò từng trường hợp bằng CJNE, mất tới 38 chu kỳ. Hãy viết để chạy không quá <b>20 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>), mã (kể cả bảng) không quá <b>48 byte<\/b>.<\/p><p>Ví dụ: 30H = 0, 31H = 04H (A = 1, B = 0), 32H = 10H → <code>30H = 1<\/code>, <code>32H = 11H<\/code>.<\/p>","start":"; Giải mã x4: 30H = trạng thái cũ (bit1 = B, bit0 = A),\n; 31H = ảnh P3 mới (A = bit 2, B = bit 3). Đúng nhưng chậm.\n        ORG     0000H\n        MOV     A,31H\n        RR      A\n        RR      A\n        ANL     A,#03H                  ; trạng thái mới\n        MOV     R3,A\n        MOV     A,30H\n        RL      A\n        RL      A\n        ORL     A,R3                    ; chỉ số = cũ x 4 + mới\n        MOV     30H,R3                  ; lưu trạng thái mới\n        CJNE    A,#1,K1                 ; thuận: 1, 7, 8, 14\n        SJMP    TANG\nK1:     CJNE    A,#7,K2\n        SJMP    TANG\nK2:     CJNE    A,#8,K3\n        SJMP    TANG\nK3:     CJNE    A,#14,K4\n        SJMP    TANG\nK4:     CJNE    A,#2,K5                 ; ngược: 2, 4, 11, 13\n        SJMP    GIAM\nK5:     CJNE    A,#4,K6\n        SJMP    GIAM\nK6:     CJNE    A,#11,K7\n        SJMP    GIAM\nK7:     CJNE    A,#13,K8\n        SJMP    GIAM\nK8:     CJNE    A,#3,K9                 ; nhảy cóc: 3, 6, 9, 12\n        SJMP    LOI\nK9:     CJNE    A,#6,K10\n        SJMP    LOI\nK10:    CJNE    A,#9,K11\n        SJMP    LOI\nK11:    CJNE    A,#12,XONG              ; còn lại: không đổi\nLOI:    INC     33H\n        SJMP    XONG\nTANG:   INC     32H\n        SJMP    XONG\nGIAM:   DEC     32H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":4,"0x32":16,"0x33":0}},"expect":{"iram":{"0x30":1,"0x31":4,"0x32":17,"0x33":0}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":16,"0x33":0}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":15,"0x33":0}}},{"setup":{"iram":{"0x30":3,"0x31":252,"0x32":32,"0x33":0}},"expect":{"iram":{"0x30":3,"0x31":252,"0x32":32,"0x33":0}}},{"setup":{"iram":{"0x30":0,"0x31":12,"0x32":32,"0x33":2}},"expect":{"iram":{"0x30":3,"0x31":12,"0x32":32,"0x33":3}}},{"setup":{"iram":{"0x30":2,"0x31":243,"0x32":127,"0x33":0}},"expect":{"iram":{"0x30":0,"0x31":243,"0x32":128,"0x33":0}}},{"setup":{"iram":{"0x30":3,"0x31":4,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":1,"0x31":4,"0x32":255,"0x33":0}}},{"setup":{"iram":{"0x30":1,"0x31":8,"0x32":5,"0x33":9}},"expect":{"iram":{"0x30":2,"0x31":8,"0x32":5,"0x33":10}}}],"maxCyc":20,"maxBytes":48},"hints":["Chỉ số = cũ × 4 + mới chỉ có 16 giá trị: lập bảng 16 byte trong bộ nhớ CODE, đọc bằng MOVC A,@A+DPTR.","Ghi vào bảng giá trị cần cộng: 01H (thuận), FFH (ngược, tức −1), 00H (không đổi); dùng một mã riêng, ví dụ 80H, cho nhảy cóc. Khi đó chỉ cần một CJNE A,#80H,… rồi ADD A,32H.","XCH A,30H vừa lấy trạng thái cũ vừa ghi trạng thái mới trong một lệnh 1 chu kỳ."],"why":"Bảng tra biến 12 phép so sánh thành một lệnh MOVC 2 chu kỳ: thời gian chương trình ngắt không còn phụ thuộc trường hợp (18 chu kỳ khi hợp lệ, 19 khi nhảy cóc), giúp tính được tần số xung lớn nhất mà không mất xung. Lời giải tham chiếu: tối đa 19 chu kỳ, 45 byte (29 byte lệnh + 16 byte bảng)."}]);

makeQuiz("quiz48","score48",[{"q": "Encoder 20 xung/vòng, kênh A đo được 1 000 Hz. Trục quay bao nhiêu vòng/phút?", "o": ["50 vòng/phút", "20 000 vòng/phút", "1 200 vòng/phút", "3 000 vòng/phút"], "a": 3, "e": "1 000 / 20 = 50 vòng/giây = 3 000 vòng/phút. 50 là số vòng mỗi giây, không phải mỗi phút."}, {"q": "Ngay sau sườn xuống của kênh A, đọc được B = 0. Với encoder của bài (quay thuận A sớm hơn B), trục đang quay chiều nào?", "o": ["Thuận", "Không xác định được", "Ngược", "Đứng yên"], "a": 2, "e": "Quay thuận, tại sườn xuống A thì B = 1; B = 0 nghĩa là quay ngược."}, {"q": "Vòng thăm dò đọc chân A mỗi 60 µs; xung kênh A 20 000/s (mỗi mức giữ 25 µs). Điều gì xảy ra?", "o": ["Đếm đúng nhưng chậm hơn", "Đếm thiếu rất nhiều vì giữa hai lần đọc A có thể đổi mức hơn một lần", "Đếm thừa gấp đôi", "Đếm đúng vì 8051 có bộ đệm chân"], "a": 1, "e": "Khoảng cách hai lần đọc phải nhỏ hơn thời gian A giữ một mức. 60 µs > 25 µs nên dãy mẫu là dãy giả (ví dụ 4: 18 thay vì 118)."}, {"q": "Mỗi lần ngắt encoder tốn 25 chu kỳ máy (kể cả lệnh gọi và RETI) ở 12 MHz; sườn đến 10 000 lần/giây. Tải CPU là?", "o": ["2,5 %", "10 %", "25 %", "40 %"], "a": 2, "e": "10 000 × 25 µs = 0,25 s mỗi giây = 25 %."}, {"q": "Theo tài liệu MCS-51, Timer 0 ở chế độ đếm sự kiện cần 2 chu kỳ máy để nhận một sườn. Ở 12 MHz, tần số đếm lớn nhất là?", "o": ["500 kHz", "1 MHz", "12 MHz", "6 MHz"], "a": 0, "e": "fosc / 24 = 12 MHz / 24 = 500 kHz (2 chu kỳ máy × 12 chu kỳ thạch anh)."}]);

fillSnips();
